// Dashboard answers are human inputs. A ready application may be recorded for standing-authorized submission.
names.approvals=['Your inbox. Your team.','Answer, review, or leave a request—all in one place.','YOUR INBOX'];
const inboxKinds=['question','application','update','instruction'];
const originalReview=review;
function dailySubmitted(){const localDay=value=>new Date(value).toLocaleDateString('en-US',{timeZone:'America/New_York'});const today=localDay(Date.now());return state.opportunities.filter(j=>(j.history||[]).some(h=>h.stage==='Applied'&&h.evidence&&localDay(h.created)===today)).length}
function inboxCard(a){return `<article class="queue-card">${badge(a.status.replaceAll('_',' '))}<h3>${esc(a.title)}</h3><p>${esc(a.kind==='question'?'Quick clarification':a.kind==='application'?'Application record':a.kind==='instruction'?'Saved request':a.kind==='document'?'Resume review':a.kind==='update'?'Team update':'Message review')}${a.version?' · Version '+a.version:''}</p><button class="secondary" data-approval="${esc(a.id)}">${a.kind==='question'&&a.status==='pending'?'Answer question':'Open details'} →</button></article>`}
approvals=function(){const live=state.approvals.filter(a=>a.status!=='superseded');const old=state.approvals.filter(a=>a.status==='superseded');return `<div class="note"><b>Daily target: ${dailySubmitted()} / 5 employer-confirmed submissions today.</b> Your team completes saved applications first, resolves specific blockers, and reports any shortfall without relaxing your requirements.</div><div class="note">When automation is active, your team checks new answers and approvals every 30 minutes, prepares applications midnight–7 AM Eastern, and handles daytime work from 9 AM. Overnight work may submit a fully verified application under your standing authorization; blocked items wait in your inbox while other applications continue. Paused automation does not pick up replies. Keep your Mac and Codex app available; pickup can take longer while the task is busy. Only an employer confirmation proves submission.</div><div class="section-head"><h2>From your team</h2><button class="primary" id="team-request">+ Leave a request</button></div><div class="queue">${live.sort((a,b)=>(b.status==='pending')-(a.status==='pending')).map(inboxCard).join('')||'<p>Nothing needs your attention.</p>'}</div>${old.length?`<details class="detail-section"><summary>Previous versions (${old.length})</summary><div class="queue">${old.map(inboxCard).join('')}</div></details>`:''}`};
review=function(id){const a=state.approvals.find(x=>x.id===id);if(!a)return;if(!inboxKinds.includes(a.kind))return originalReview(id);modal(`<div class="eyebrow">${esc(a.kind)}${a.version?' · VERSION '+a.version:''}</div><h2 class="detail-title">${esc(a.title)}</h2>${badge(a.status.replaceAll('_',' '))}<p class="message-body" style="margin-top:20px">${esc(a.body)}</p>${(a.sections||[]).map(s=>`<details class="detail-section"><summary>${esc(s.title)}</summary><ul>${s.items.map(i=>`<li>${esc(i)}</li>`).join('')}</ul></details>`).join('')}${Object.keys(a.documents||{}).map(d=>`<div class="actions"><a class="secondary" href="/documents/${encodeURIComponent(d)}" target="_blank" rel="noopener noreferrer">Read ${esc(d==='amex'?'American Express resume':d)} PDF ↗</a></div>`).join('')}${a.status==='blocked'?'<div class="note">Preparation is still in progress. The application cannot be submitted until all required facts and checks are complete.</div>':''}${a.status==='needs_refresh'?'<div class="note">The attached document changed. The team must audit and publish an updated record before submission.</div>':''}${a.answers?`<div class="detail-section"><h3>Your saved answers</h3>${(a.questions||[]).map(q=>`<p><b>${esc(q.label)}</b><br>${esc(a.answers[q.id])}</p>`).join('')}</div>`:''}${a.response_note?`<p>Your note: ${esc(a.response_note)}</p>`:''}${a.responded_at?`<p class="caption">Saved ${new Date(a.responded_at).toLocaleString()}</p>`:''}<form id="inbox-response">${a.status==='pending'&&a.kind==='question'?(a.questions||[]).map((q,i)=>`<label>${esc(q.label)}<textarea name="answer-${i}" required placeholder="Type your answer, or choose a suggestion below."></textarea></label><div class="actions">${q.options.map(o=>`<button type="button" class="secondary" data-suggestion="${esc(o)}" data-answer="${i}">${esc(o)}</button>`).join('')}</div>`).join(''):''}${a.status==='pending'&&a.kind==='application'?'<div class="note">This older review predates automatic submission. The team must revalidate and republish it before taking action; you do not need to approve it.</div>':''}<p class="form-error" hidden></p><div class="actions">${a.status==='pending'&&a.kind==='question'?'<button class="primary" type="submit">Save answers</button>':''}${a.status==='pending'&&a.kind==='update'?'<button class="primary" type="submit">Mark read</button>':''}${['approved','ready_auto_submit'].includes(a.status)&&a.kind==='application'?'<button class="secondary" type="button" id="inbox-withdraw">Stop automatic submission</button>':''}</div></form>`);
const form=$('#inbox-response');const decide=async decision=>{const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{const answers=Object.fromEntries((a.questions||[]).map((q,i)=>[q.id,form.elements['answer-'+i]?.value||'']));await api('/api/inbox/respond',{id:a.id,fingerprint:a.fingerprint,decision,answers,note:form.elements.note?.value||'',reviewed:$('#inbox-check')?.checked===true});await load();review(a.id);message('Saved. Active automation checks replies every 30 minutes; paused automation waits until resumed.')}catch(e){form.querySelector('.form-error').hidden=false;form.querySelector('.form-error').textContent=e.message;buttons.forEach(b=>b.disabled=false);if($('#inbox-approve'))$('#inbox-approve').disabled=!$('#inbox-check').checked}};
form.onsubmit=e=>{e.preventDefault();decide(a.kind==='question'?'answered':a.kind==='update'?'acknowledged':'approved')};form.querySelectorAll('[data-suggestion]').forEach(b=>b.onclick=()=>{form.elements['answer-'+b.dataset.answer].value=b.dataset.suggestion});if($('#inbox-check'))$('#inbox-check').onchange=e=>$('#inbox-approve').disabled=!e.target.checked;if($('#inbox-changes'))$('#inbox-changes').onclick=()=>decide('changes_requested');if($('#inbox-withdraw'))$('#inbox-withdraw').onclick=()=>decide('withdrawn');};
document.addEventListener('click',e=>{if(e.target.closest('#team-request')){modal(`<div class="eyebrow">YOUR TEAM</div><h2 class="detail-title">What should we work on?</h2><form id="team-request-form"><label>Request or correction<textarea name="body" required maxlength="10000" placeholder="Add information, request a change, or tell the team what to do next."></textarea></label><p class="caption">Active automation checks new requests every 30 minutes while your Mac and Codex app are available. Paused automation waits until resumed.</p><p class="form-error" hidden></p><button class="primary" type="submit">Save request</button></form>`);$('#team-request-form').onsubmit=e=>submit(e,'/api/inbox/instruction',{},()=>{close();navigate('approvals');message('Request saved for your team.')})}});
const originalSyncWorkers=syncWorkers;
syncWorkers=function(){originalSyncWorkers();const a=state.approvals.find(a=>a.kind==='application'&&a.status!=='superseded');if(a){workers[2].status=a.status==='blocked'?'Completeness review':'Application draft ready';workers[2].details='Relevant skills, languages, certifications, education and experience are checked against your resume and confirmed answers. Read the application review in Your inbox.';workers[3].status=a.status==='ready_auto_submit'?'Ready for automatic submission':a.status==='approved'?'Approved · awaiting execution':a.status==='pending'?'Revalidation pending':'Preparing application';workers[3].details='The assistant prepares the employer portal and records progress here. The standing instruction permits automatic submission only after the full council, truthful form, permissions, completeness audit and live employer checks pass.'}};
if(location.hash==='#inbox')view='approvals';window.addEventListener('hashchange',()=>{if(location.hash==='#inbox')navigate('approvals')});
load();
